import { defineConfig } from "oxfmt";
import ultracite from "ultracite/oxfmt";

const sortTailwindcss =
  typeof ultracite.sortTailwindcss === "object"
    ? ultracite.sortTailwindcss
    : {};

export default defineConfig({
  ...ultracite,
  // Generated by design/scripts/build-tokens.ts; formatting it would break the freshness check.
  ignorePatterns: [
    ...(ultracite.ignorePatterns ?? []),
    "apps/web/src/styles/tokens.css",
  ],
  // Without the real theme, Paper utilities sort as unknown custom classes.
  sortTailwindcss: {
    ...sortTailwindcss,
    stylesheet: "./apps/web/src/app/globals.css",
  },
});
